00059     public static function findExeByPid($pid)
00060     {
00061         // Sanitize PID to prevent command injection
00062         $sanitizedPid = UtilInput::sanitizePID($pid);
00063         if ($sanitizedPid === false) {
00064             self::writeLog('Invalid PID provided to findExeByPid: ' . var_export($pid, true));
00065             return false;
00066         }
00067 
00068         $result = self::exec('findExeByPid', 'TASKLIST /FO CSV /NH /FI "PID eq ' . $sanitizedPid . '"', 5);
00069         if ($result !== false) {
00070             $expResult = explode('","', $result[0]);
00071             if (is_array($expResult) && count($expResult) > 2 && isset($expResult[0]) && !empty($expResult[0])) {
00072                 return substr($expResult[0], 1);
00073             }
00074         }
00075 
00076         return false;
00077     }
