00085     public static function getProcessUsingPort($port)
00086     {
00087         // Sanitize port to prevent command injection
00088         $sanitizedPort = UtilInput::sanitizePort($port);
00089         if ($sanitizedPort === false) {
00090             self::writeLog('Invalid port provided to getProcessUsingPort: ' . var_export($port, true));
00091             return null;
00092         }
00093 
00094         $result = self::exec('getProcessUsingPort', 'NETSTAT -aon', 4);
00095         if ($result !== false) {
00096             foreach ($result as $row) {
00097                 if (!UtilString::startWith($row, 'TCP')) {
00098                     continue;
00099                 }
00100                 $rowExp = explode(' ', preg_replace('/\s+/', ' ', $row));
00101                 if (count($rowExp) == 5 && UtilString::endWith($rowExp[1], ':' . $sanitizedPort) && $rowExp[3] == 'LISTENING') {
00102                     $pid = intval($rowExp[4]);
00103                     $exe = self::findExeByPid($pid);
00104                     if ($exe !== false) {
00105                         return $exe . ' (' . $pid . ')';
00106                     }
00107                     return $pid;
00108                 }
00109             }
00110         }
00111 
00112         return null;
00113     }
