00120     public static function exitApp($restart = false)
00121     {
00122         global $bearsamppRoot, $bearsamppCore;
00123 
00124         $content = 'PING 1.1.1.1 -n 1 -w 2000 > nul' . PHP_EOL;
00125         $content .= '"' . Path::getExeFilePath() . '" -quit -id={bearsampp}' . PHP_EOL;
00126         if ($restart) {
00127             $basename = 'restartApp';
00128             Log::info('Restart App');
00129             $content .= '"' . Path::getPhpExe() . '" "' . Core::isRoot_FILE . '" "' . Action::RESTART . '"' . PHP_EOL;
00130         } else {
00131             $basename = 'exitApp';
00132             Log::info('Exit App');
00133         }
00134 
00135         Win32Ps::killBins();
00136         self::execStandalone($basename, $content);
