00199     public static function installPostgresqlService()
00200     {
00201         global $bearsamppBins;
00202 
00203         $cmd = '"' . Path::formatWindowsPath($bearsamppBins->getPostgresql()->getCtlExe()) . '" register -N "' . BinPostgresql::SERVICE_NAME . '"';
00204         $cmd .= ' -U "LocalSystem" -D "' . Path::formatWindowsPath(Path::getModuleSymlinkPath($bearsamppBins->getPostgresql())) . '\\data"';
00205         $cmd .= ' -l "' . Path::formatWindowsPath($bearsamppBins->getPostgresql()->getErrorLog()) . '" -w';
00206         self::exec('installPostgresqlService', $cmd, true, false);
00207 
00208         if (!$bearsamppBins->getPostgresql()->getService()->isInstalled()) {
00209             return false;
00210         }
00211 
00212         self::setServiceDisplayName(BinPostgresql::SERVICE_NAME, $bearsamppBins->getPostgresql()->getService()->getDisplayName());
00213         self::setServiceDescription(BinPostgresql::SERVICE_NAME, $bearsamppBins->getPostgresql()->getService()->getDisplayName());
00214         self::setServiceStartType(BinPostgresql::SERVICE_NAME, "demand");
00215 
00216         return true;
00217     }
