00282     public static function removeSymlink($link)
00283     {
00284         if (!file_exists($link)) {
00285             self::writeLog('-> removeSymlink: Link does not exist: ' . $link);
00286             return true; // If the link doesn't exist, nothing to do
00287         }
00288 
00289         // Check if it's a directory symlink
00290         $isDirectory = is_dir($link);
00291         $formattedLink = Path::formatWindowsPath($link);
00292 
00293         try {
00294             // Use different commands based on whether it's a directory or file symlink
00295             if ($isDirectory) {
00296                 // For directory symlinks
00297                 self::exec('removeSymlink', 'rmdir /Q "' . $formattedLink . '"', true, false);
00298             } else {
00299                 // For file symlinks
00300                 self::exec('removeSymlink', 'del /F /Q "' . $formattedLink . '"', true, false);
00301             }
00302 
00303             // Check if removal was successful
00304             if (file_exists($link)) {
00305                 self::writeLog('-> removeSymlink: Failed to remove symlink: ' . $link);
00306                 return false;
00307             }
00308 
00309             self::writeLog('-> removeSymlink: Successfully removed symlink: ' . $link);
00310             return true;
00311         } catch (Exception $e) {
00312             self::writeLog('-> removeSymlink: Exception: ' . $e->getMessage());
00313             return false;
00314         }
00315     }
