00341     public static function setServiceDisplayName($serviceName, $displayName)
00342     {
00343         // Sanitize service name to prevent command injection
00344         $sanitizedName = UtilInput::sanitizeServiceName($serviceName);
00345         if ($sanitizedName === false) {
00346             self::writeLog('Invalid service name provided to setServiceDisplayName: ' . $serviceName);
00347             return;
00348         }
00349 
00350         // Remove quotes and dangerous characters from display name
00351         $sanitizedDisplayName = str_replace('"', '', $displayName);
00352         $sanitizedDisplayName = preg_replace('/[<>|&^]/', '', $sanitizedDisplayName);
00353 
00354         $cmd = 'sc config ' . $sanitizedName . ' DisplayName= "' . $sanitizedDisplayName . '"';
00355         self::exec('setServiceDisplayName', $cmd, true, false);
