00387     public static function setServiceStartType($serviceName, $startType)
00388     {
00389         // Sanitize service name to prevent command injection
00390         $sanitizedName = UtilInput::sanitizeServiceName($serviceName);
00391         if ($sanitizedName === false) {
00392             self::writeLog('Invalid service name provided to setServiceStartType: ' . $serviceName);
00393             return;
00394         }
00395 
00396         // Validate start type (only allow known values)
00397         $allowedStartTypes = ['auto', 'demand', 'disabled', 'delayed-auto'];
00398         if (!in_array(strtolower($startType), $allowedStartTypes, true)) {
00399             self::writeLog('Invalid start type provided: ' . $startType);
00400             return;
00401         }
00402 
00403         $cmd = 'sc config ' . $sanitizedName . ' start= ' . strtolower($startType);
00404         self::exec('setServiceStartType', $cmd, true, false);
00405     }
