00432     public static function exec($basename, $content, $timeout = true, $catchOutput = true, $standalone = false, $silent = true, $rebuild = true)
00433     {
00434         global $bearsamppConfig, $bearsamppWinbinder;
00435         $result = false;
00436 
00437         $resultFile = self::getTmpFile('.tmp', $basename);
00438         $scriptPath = self::getTmpFile('.bat', $basename);
00439         $checkFile = self::getTmpFile('.tmp', $basename);
00440 
00441         // Redirect output
00442         if ($catchOutput) {
00443             $content = '(' . PHP_EOL . $content . PHP_EOL . ') > "' . $resultFile . '"' . (!UtilString::endWith($content, '2') ? ' 2>&1' : '');
00444         }
00445 
00446         // Header
00447         $header = '@ECHO OFF' . PHP_EOL . PHP_EOL;
00448 
00449         // Footer
00450         $footer = PHP_EOL . (!$standalone ? PHP_EOL . 'ECHO ' . self::END_PROCESS_STR . ' > "' . $checkFile . '"' : '');
00451 
00452         // Process
00453         file_put_contents($scriptPath, $header . $content . $footer);
00454 
00455         if (is_object($bearsamppWinbinder)) {
00456             $bearsamppWinbinder->exec($scriptPath, null, $silent);
00457         } else {
00458             // Fallback to standard PHP execution if WinBinder is not available (e.g. on web interface)
00459             $cmd = 'cmd /c "' . $scriptPath . '"';
00460             if ($silent) {
00461                 // Use shell_exec with output redirection to NUL for silent background execution on Windows
00462                 @shell_exec('start /B "" ' . $cmd . ' > NUL 2>&1');
00463             } else {
00464                 @shell_exec($cmd);
00465             }
00466         }
00467 
00468         if (!$standalone) {
00469             $timeout = is_numeric($timeout) ? $timeout : ($timeout === true ? $bearsamppConfig->getScriptsTimeout() : false);
00470             $maxtime = time() + $timeout;
00471             $noTimeout = $timeout === false;
00472             while ($result === false || empty($result)) {
00473                 if (file_exists($checkFile)) {
00474                     $check = file($checkFile);
00475                     if (!empty($check) && trim($check[0]) == self::END_PROCESS_STR) {
00476                         if ($catchOutput && file_exists($resultFile)) {
00477                             $result = file($resultFile);
00478                         } else {
00479                             $result = self::CATCH_OUTPUT_FALSE;
00480                         }
00481                     }
00482                 }
00483                 if ($maxtime < time() && !$noTimeout) {
00484                     break;
00485                 }
00486             }
00487         }
00488 
00489         self::writeLog('Exec:');
00490         self::writeLog('-> basename: ' . $basename);
00491         self::writeLog('-> content: ' . str_replace(PHP_EOL, ' \\\\ ', $content));
00492         self::writeLog('-> checkFile: ' . $checkFile);
00493         self::writeLog('-> resultFile: ' . $resultFile);
00494         self::writeLog('-> scriptPath: ' . $scriptPath);
00495 
00496         if ($result !== false && !empty($result) && is_array($result)) {
00497             if ($rebuild) {
00498                 $rebuildResult = array();
00499                 foreach ($result as $row) {
00500                     $row = trim($row);
00501                     if (!empty($row)) {
00502                         $rebuildResult[] = $row;
00503                     }
00504                 }
00505                 $result = $rebuildResult;
00506             }
00507             self::writeLog('-> result: ' . substr(implode(' \\\\ ', $result), 0, 2048));
00508         } else {
00509             self::writeLog('-> result: N/A');
00510         }
00511 
00512         return $result;
00513     }
